import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem
def kabsch(P,Q):
    H=P.T@Q; U,S,Vt=np.linalg.svd(H); d=np.sign(np.linalg.det(Vt.T@U.T))
    return Vt.T@np.diag([1,1,d])@U.T
px={1:(155,88),2:(155,133),3:(198,152),4:(245,133),10:(245,88),11:(198,63)}
order=[1,2,3,4,10,11]
tgt=np.array([[px[i][0]/30.0,-px[i][1]/30.0,0.0] for i in order]); tgt-=tgt.mean(axis=0)
for s in ["BrC1=C[C+][C@@H]2N(C)C(=O)C[C@@H]2C1","BrC1=C[C+][C@H]2N(C)C(=O)C[C@H]2C1"]:
    m=Chem.MolFromSmiles(s); m=Chem.AddHs(m)
    AllChem.EmbedMolecule(m,randomSeed=11); AllChem.MMFFOptimizeMolecule(m)
    P=m.GetConformer().GetPositions(); c0=P[order].mean(axis=0)
    Pl=(P-c0)@kabsch(P[order]-c0,tgt).T
    Hs={}
    for idx in (4,10):
        for nb in m.GetAtomWithIdx(idx).GetNeighbors():
            if nb.GetSymbol()=='H': Hs[idx]=nb.GetIdx()
    z5=np.mean([Pl[i][2] for i in (4,5,6,7,10)])
    print(s, 'zH4 %.2f zH10 %.2f  z5ring %.2f'%(Pl[Hs[4]][2],Pl[Hs[10]][2],z5))
