import numpy as np
lines=open('complex_raw.xyz').read().split('\n')[2:]
at=[l.split() for l in lines if l.strip()]
A=np.array([[float(x) for x in r[1:4]] for r in at]); sym=[r[0] for r in at]
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'P':1.07,'B':0.84,'W':1.70}
import networkx as nx
G=nx.Graph(); G.add_nodes_from(range(len(A)))
for i in range(len(A)):
    for j in range(i+1,len(A)):
        d=np.linalg.norm(A[i]-A[j])
        if d < 1.25*(cov[sym[i]]+cov[sym[j]]):
            G.add_edge(i,j)
for c in nx.connected_components(G):
    if len(c)<len(A): print('component', sorted(c), [sym[i] for i in sorted(c)])
print('ncomp', nx.number_connected_components(G))
# print bonds of atom 0..3
for i in (0,1,2,3):
    print(i, sym[i], [(j,sym[j],round(float(np.linalg.norm(A[i]-A[j])),2)) for j in G.neighbors(i)])
