def frag(i):
    if i<21: return 'lig'
    if i<24: return 'core'
    if i<37: return 'pme'
    return 'tp'
ps=[]
for i in range(len(A)):
    for j in range(i+1,len(A)):
        if frag(i)!=frag(j):
            d=np.linalg.norm(A[i]-A[j])
            if d<2.0: ps.append((round(float(d),2),i,j,sym[i],sym[j],frag(i),frag(j)))
ps.sort()
for p in ps: print(p)
